 if v=3 then sig:=md5(jsonb_build_object('v',3,'kind',k,'id',rid,'base',base,'payload',payload)::text);
 else sig:=md5(jsonb_build_object('kind',k,'id',rid,'base',base,'payload',payload)::text);end if;
